// src/pages/HomePage.js
import { Link } from 'react-router-dom';
import { useItems } from '../hooks/useItems';

export default function HomePage() {
  const { data: items, isPending, isError } = useItems();

  if (isPending) {
    return (
      <div className="page">
        <h1 className="page-title">Campus Lost &amp; Found</h1>
        <p>Loading items...</p>
      </div>
    );
  }

  if (isError) {
    return (
      <div className="page">
        <h1 className="page-title">Campus Lost &amp; Found</h1>
        <p className="error">Failed to load items. Please try again.</p>
      </div>
    );
  }

  return (
    <div className="page">
      <h1 className="page-title">Campus Lost &amp; Found</h1>
      <p className="page-subtitle">
        Browse lost and found items reported across the campus.
      </p>

      {!items || items.length === 0 ? (
        <p>No items are currently listed.</p>
      ) : (
        <div className="grid">
          {items.map((item) => (
            <div className="card" key={item.id}>
              <h2 className="card-title">{item.title}</h2>
              <p className="card-meta">
                {item.status && (
                  <span className={`badge badge-${item.status}`}>
                    {item.status}
                  </span>
                )}
                {item.location && (
                  <span className="card-location">@ {item.location}</span>
                )}
              </p>
              <p className="card-description">
                {item.description || 'No description available.'}
              </p>
              <Link
                to={`/items/${item.id}`}
                className="btn btn-primary"
              >
                View details
              </Link>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
