// src/pages/SignInPage.js
import { Formik, Form, Field, ErrorMessage } from 'formik';
import * as Yup from 'yup';
import { useDispatch } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { signIn } from '../features/authSlice';

// 1) Validation rules using Yup
const signInSchema = Yup.object({
  name: Yup.string().required('Name is required'),
  email: Yup.string()
    .email('Please enter a valid email')
    .required('Email is required'),
});

export default function SignInPage() {
  const dispatch = useDispatch();
  const navigate = useNavigate();

  return (
    <div>
      <h1>Sign In</h1>
      <p>Please enter your name and campus email.</p>

      {/* 2) Formik wrapper */}
      <Formik
        initialValues={{ name: '', email: '' }}
        validationSchema={signInSchema}
        onSubmit={(values) => {
          // 3) Here we "fake" a logged-in user
          const fakeUser = {
            id: 'u1', // in a real app this comes from the backend
            name: values.name,
            email: values.email,
          };

          // Save user in Redux store
          dispatch(signIn(fakeUser));

          // Go back to Home page after sign in
          navigate('/');
        }}
      >
        {/* Formik gives us <Form> to wrap inputs */}
        <Form style={{ maxWidth: '300px' }}>
          {/* Name field */}
          <div style={{ marginBottom: '1rem' }}>
            <label htmlFor="name">Name</label>
            <br />
            <Field
              id="name"
              name="name"
              placeholder="Enter your name"
              style={{ width: '100%' }}
            />
            <ErrorMessage
              name="name"
              component="div"
              style={{ color: 'red', fontSize: '0.8rem' }}
            />
          </div>

          {/* Email field */}
          <div style={{ marginBottom: '1rem' }}>
            <label htmlFor="email">Email</label>
            <br />
            <Field
              id="email"
              name="email"
              placeholder="you@campus.edu"
              style={{ width: '100%' }}
            />
            <ErrorMessage
              name="email"
              component="div"
              style={{ color: 'red', fontSize: '0.8rem' }}
            />
          </div>

          {/* Submit button */}
          <button type="submit">Sign In</button>
        </Form>
      </Formik>
    </div>
  );
}
