// src/pages/ItemDetailsPage.js
import { useParams, useNavigate } from 'react-router-dom';
import { useItem } from '../hooks/useItems';
import { useAuth } from '../hooks/useAuth';
import { useInterestMutation } from '../hooks/useInterests';
import { useClaimItem } from '../hooks/useClaimItem';

export default function ItemDetailsPage() {
  // get :id from URL (e.g. /items/i1)
  const { id } = useParams();

  // fetch this item from backend
  const { data: item, isPending, isError } = useItem(id);

  // current logged in user (from Redux)
  const user = useAuth();

  // to redirect to /signin if needed
  const navigate = useNavigate();

  // mutation for "I'm interested"
  const interestMutation = useInterestMutation(user?.id);

  // mutation for "Mark as claimed"
  const claimMutation = useClaimItem();

  if (isPending) {
    return <p>Loading item...</p>;
  }

  if (isError || !item) {
    return <p>Item not found.</p>;
  }

  const handleInterestedClick = () => {
    // if not logged in, go to Sign In
    if (!user) {
      navigate('/signin');
      return;
    }

    // send POST /interests
    interestMutation.mutate(item.id);
  };

  const handleMarkClaimedClick = () => {
    // if not logged in, go to Sign In
    if (!user) {
      navigate('/signin');
      return;
    }

    // if already claimed, do nothing
    if (item.claimed) {
      return;
    }

    // send PATCH /items/:id with claimed: true
    claimMutation.mutate(item.id);
  };

  return (
    <div>
      <h2>{item.title}</h2>

      <p>
        <strong>Description:</strong> {item.description}
      </p>
      <p>
        <strong>Status:</strong> {item.status}
      </p>
      <p>
        <strong>Location:</strong> {item.location}
      </p>
      <p>
        <strong>Claimed:</strong> {item.claimed ? 'Yes' : 'No'}
      </p>

      {/* I'm interested button */}
      <button
        onClick={handleInterestedClick}
        disabled={interestMutation.isPending}
      >
        {interestMutation.isPending ? 'Sending...' : "I'm interested"}
      </button>

      {interestMutation.isError && (
        <p style={{ color: 'red' }}>
          Could not send your interest. Please try again.
        </p>
      )}

      {interestMutation.isSuccess && (
        <p style={{ color: 'green' }}>
          We recorded your interest in this item.
        </p>
      )}

      <hr style={{ margin: '1rem 0' }} />

      {/* Mark as claimed button */}
      <button
        onClick={handleMarkClaimedClick}
        disabled={claimMutation.isPending || item.claimed}
        style={{ marginTop: '0.5rem' }}
      >
        {item.claimed
          ? 'Already claimed'
          : claimMutation.isPending
          ? 'Marking...'
          : 'Mark as claimed'}
      </button>

      {claimMutation.isError && (
        <p style={{ color: 'red' }}>
          Could not mark as claimed. Please try again.
        </p>
      )}

      {claimMutation.isSuccess && (
        <p style={{ color: 'green' }}>Item marked as claimed.</p>
      )}
    </div>
  );
}
